imm('ICI_PNEUM_G2',c('pneumonitis_grade','==',2),'withhold','Grade 2 immune pneumonitis: withhold pembrolizumab until grade 0–1; recurrent grade 2 permanently stops it.')
imm('ICI_PNEUM_G3',oo(c('pneumonitis_grade','>=',3),c('pneumonitis_recurrent_g2','==',True)),'permanently_discontinue','Grade 3–4 or recurrent grade 2 immune pneumonitis: permanently discontinue pembrolizumab.')
imm('ICI_COLITIS_G2',c('diarrhoea_colitis_grade','in',[2,3]),'withhold','Grade 2–3 immune colitis: withhold until grade 0–1; recurrent grade 3 requires permanent discontinuation.')
imm('ICI_COLITIS_STOP',oo(c('diarrhoea_colitis_grade','==',4),c('colitis_recurrent_g3','==',True)),'permanently_discontinue','Grade 4 or recurrent grade 3 immune colitis: permanently discontinue pembrolizumab.')
hep=oo(c('hepatic_toxicity_attribution','==','immune'),aa(miss('hepatic_toxicity_attribution'),c('immune_hepatitis_grade','>=',2)));ren=oo(c('renal_toxicity_attribution','==','immune'),aa(miss('renal_toxicity_attribution'),c('immune_nephritis_grade','>=',2)))
imm('ICI_HEP_G2',aa(hep,oo(aa(c('alt_ast_uln_multiple','>',3),c('alt_ast_uln_multiple','<=',5)),aa(c('bilirubin_uln_multiple','>',1.5),c('bilirubin_uln_multiple','<=',3)))),'withhold','Immune hepatitis with AST/ALT >3–5 ×ULN or bilirubin >1.5–3 ×ULN: withhold pembrolizumab; confirm grade, attribution and baseline liver metastasis exception.')
imm('ICI_HEP_G3',aa(hep,oo(c('alt_ast_uln_multiple','>',5),c('bilirubin_uln_multiple','>',3))),'permanently_discontinue','Immune hepatitis with AST/ALT >5 ×ULN or bilirubin >3 ×ULN: permanent pembrolizumab discontinuation. Cytotoxic hepatic decisions remain separate.')
imm('ICI_HEP_GRADE_ONLY_REVIEW',aa(c('immune_hepatitis_grade','>=',2),miss('alt_ast_uln_multiple'),miss('bilirubin_uln_multiple')),'withhold','Immune hepatitis grade without biochemical criteria: withhold and verify actual values/ULNs, baseline liver disease and attribution before permanent-stop decision.')
imm('ICI_HEP_LIVER_METASTASIS_STOP',aa(hep,c('baseline_grade2_liver_metastases','==',True),c('hepatic_increase_percent','>=',50),c('hepatic_increase_days','>=',7)),'permanently_discontinue','Liver metastases with baseline grade 2 AST/ALT and hepatitis with ≥50% rise lasting ≥1 week: permanently discontinue pembrolizumab.',5 if cis else 6)
imm('ICI_RENAL_G2',aa(ren,c('creatinine_uln_multiple','>',1.5),c('creatinine_uln_multiple','<=',3)),'withhold','Immune nephritis with creatinine >1.5 to ≤3 ×ULN: withhold pembrolizumab; confirm clinical grade and exclude other causes.')
imm('ICI_RENAL_G3',aa(ren,c('creatinine_uln_multiple','>',3)),'permanently_discontinue','Immune nephritis with creatinine >3 ×ULN: permanently discontinue pembrolizumab; distinguish platinum nephrotoxicity.')
imm('ICI_RENAL_GRADE_ONLY_REVIEW',aa(c('immune_nephritis_grade','>=',2),miss('creatinine_uln_multiple')),'withhold','Immune nephritis grade without creatinine ×ULN: withhold while confirming biochemical criteria/attribution; no permanent-stop inference from grade alone.')
for domain,w in [('HEPATIC',oo(c('alt_ast_uln_multiple','>',3),c('bilirubin_uln_multiple','>',1.5))),('RENAL',c('creatinine_uln_multiple','>',1.5))]:
 f='hepatic_toxicity_attribution'if domain=='HEPATIC'else'renal_toxicity_attribution';g='immune_hepatitis_grade'if domain=='HEPATIC'else'immune_nephritis_grade'
 imm(domain+'_ATTRIBUTION_REVIEW',aa(w,oo(miss(f),c(f,'==','uncertain')),oo(miss(g),c(g,'<',2))),'consultant_review','Abnormal organ values require attribution/evaluation. A lab alone must not become an immune-mediated permanent-stop diagnosis.')
imm('ICI_ENDO_G3',aa(c('immune_endocrinopathy_grade','>=',3),oo(miss('endocrine_type'),c('endocrine_type','in',['adrenal','hypophysitis','hyperthyroidism','type1_diabetes','other'])),oo(miss('endocrine_controlled'),c('endocrine_controlled','==',False))),'withhold','Severe immune endocrinopathy: withhold until stabilised. Continuation may be considered at grade ≤2 controlled by replacement after needed steroid taper; otherwise discontinue.')
imm('ICI_ENDO_G2',aa(c('endocrine_type','in',['adrenal','hypophysitis']),c('immune_endocrinopathy_grade','==',2),oo(miss('endocrine_controlled'),c('endocrine_controlled','==',False))),'withhold','Grade 2 adrenal insufficiency/hypophysitis: withhold until controlled by hormone replacement.')
imm('ICI_ENDO_CONTROLLED',aa(c('endocrine_controlled','==',True),c('immune_endocrinopathy_grade','<=',2)),'consultant_review','Controlled endocrinopathy at grade ≤2: continuation may be considered after needed taper; no blanket permanent-stop for a controlled endocrine disorder.')
imm('ICI_HYPOTHYROID',c('endocrine_type','==','hypothyroidism'),'consultant_review','Hypothyroidism may be managed with replacement without pembrolizumab interruption; assess stability and independent toxicities.')
imm('ICI_DKA',c('ketoacidosis','==',True),'withhold','Immune type 1 diabetes with ketoacidosis requires urgent treatment and withholding until controlled.')
imm('ICI_SKIN_HOLD',oo(c('immune_skin_grade','==',3),c('sjs_ten_suspected','==',True)),'withhold','Grade 3 skin reaction or suspected SJS/TEN: withhold and arrange urgent specialist evaluation.',5 if cis else 6)
imm('ICI_SKIN_STOP',oo(c('immune_skin_grade','==',4),c('sjs_ten_confirmed','==',True)),'permanently_discontinue','Grade 4 skin reaction or confirmed SJS/TEN: permanently discontinue pembrolizumab.',5 if cis else 6)
imm('ICI_OTHER_HOLD',c('other_immune_grade','in',[2,3]),'withhold','Other grade 2–3 immune toxicity: withholding depends on severity/type; specialist evaluation and source-specific management.',5 if cis else 6)
imm('ICI_OTHER_STOP',oo(c('other_immune_grade','==',4),c('other_immune_recurrent_g3','==',True),c('immune_critical_type','in',['myocarditis_g3_g4','encephalitis_g3_g4','gbs_g3_g4'])),'permanently_discontinue','Grade 4/recurrent grade 3 other immune toxicity or grade 3–4 myocarditis, encephalitis or Guillain–Barré syndrome: permanently discontinue; endocrine exceptions assessed separately.',5 if cis else 6)
imm('ICI_CRITICAL',c('immune_neurological_or_cardiac_toxicity','==',True),'withhold','Suspected immune cardiac/neurological toxicity needs urgent evaluation and withholding; establish type/grade before permanent-stop criteria.',5 if cis else 6)
imm('ICI_INFUSION_STOP',c('pembro_infusion_grade','>=',3),'permanently_discontinue','Grade 3–4 pembrolizumab infusion reaction: permanently discontinue.',5 if cis else 6)
imm('ICI_PRIOR_STOP',c('immune_prior_permanent_stop','==',True),'permanently_discontinue','Prior immune reaction met permanent-discontinuation criteria; current improvement does not reset history.',6)
imm('ICI_12_WEEK_UNRESOLVED',aa(c('immune_unresolved_weeks','>=',12),c('immune_recovered_grade01','==',False),oo(miss('endocrine_type'),c('endocrine_controlled','==',False))),'permanently_discontinue','Immune toxicity unresolved to grade 0–1 within 12 weeks: permanently discontinue, applying controlled-endocrinopathy exceptions.',6)
imm('ICI_STEROID_12_WEEK_STOP',aa(c('steroid_taper_weeks','>=',12),c('current_prednisone_mg_day','>',10)),'permanently_discontinue','Cannot taper to ≤10 mg prednisone equivalent/day within 12 weeks of last dose: permanently discontinue pembrolizumab.',6)
imm('ICI_RESTART_REVIEW',c('assessment_phase','==','restart'),'consultant_review','Restart is a Consultant decision: prior permanent-stop/recurrence, recovery, interval and steroid taper must be checked. No pembrolizumab dose reduction recommended.',7)
# Named symptomatic hypophysitis and diabetes criteria remain distinct from broad endocrine grade.
D['symptomatic_hypophysitis']=boolean('Symptomatic immune hypophysitis')
D['immune_diabetes_glucose_mmol_l']=num('Glucose in immune-mediated type 1 diabetes','mmol/L')
imm('ICI_HYPOPHYSITIS_SYMPTOMATIC',aa(c('symptomatic_hypophysitis','==',True),oo(miss('endocrine_controlled'),c('endocrine_controlled','==',False))),'withhold','Symptomatic hypophysitis: withhold until controlled with hormone replacement; urgent endocrine assessment.')
imm('ICI_TYPE1_HYPERGLYCAEMIA',aa(c('endocrine_type','==','type1_diabetes'),c('immune_diabetes_glucose_mmol_l','>',13.9)),'withhold','Immune type 1 diabetes with glucose above 13.9 mmol/L (source grade ≥3 hyperglycaemia threshold): withhold until controlled; assess ketones/ketoacidosis urgently.')
# Grade/lab disagreement must not become silent clearance.
imm('ICI_HEP_DISCORDANT_REVIEW',aa(c('immune_hepatitis_grade','>=',2),c('alt_ast_uln_multiple','<=',3),c('bilirubin_uln_multiple','<=',1.5)),'consultant_review','Entered immune-hepatitis grade and laboratory ranges disagree. Verify timing, laboratory ULNs, attribution and grade before decisions.')
imm('ICI_RENAL_DISCORDANT_REVIEW',aa(c('immune_nephritis_grade','>=',2),c('creatinine_uln_multiple','<=',1.5)),'consultant_review','Entered immune-nephritis grade and creatinine range disagree. Verify measurements, baseline, attribution and clinical grade.')

for domain,field,gradefield in [('HEPATIC','hepatic_toxicity_attribution','immune_hepatitis_grade'),('RENAL','renal_toxicity_attribution','immune_nephritis_grade')]:
 imm(domain+'_ATTRIBUTION_CONFLICT',aa(c(field,'in',['cytotoxic','other']),c(gradefield,'>=',2)),'consultant_review','Named immune grade conflicts with explicit non-immune attribution. Resolve before immune permanent-stop criteria; independent cytotoxic actions remain assessed.')
imm('ICI_ENDO_12_WEEK_CONTEXT',aa(c('immune_unresolved_weeks','>=',12),c('immune_recovered_grade01','==',False),c('endocrine_type','exists'),miss('endocrine_controlled')),'consultant_review','At the 12-week limit confirm whether the controlled-endocrinopathy exception applies; missing control status cannot establish continuation or permanent stopping.')
